  '{added} added, {updated} updated, {kept} kept, {skipped} skipped.': '{added} προστέθηκαν, {updated} ενημερώθηκαν, {kept} διατηρήθηκαν, {skipped} παραλείφθηκαν.',
  'Kept beside: {names}.': 'Διατηρήθηκαν δίπλα: {names}.',
