  'Axis style': 'Στυλ άξονα',
  'Make a layered wall from solids': 'Δημιουργία πολυστρωματικού τοίχου από στερεά',
  'The selected solids, side by side across a wall, one per layer, become one wall of a type with those layers, with the openings that go through all of them.': 'Τα επιλεγμένα στερεά, το ένα δίπλα στο άλλο κατά το πάχος ενός τοίχου, ένα ανά στρώση, γίνονται ένας τοίχος τύπου με αυτές τις στρώσεις, με τα ανοίγματα που τα διαπερνούν όλα.',
  'Gaps between layers': 'Κενά μεταξύ στρώσεων',
