  'What is set here is this side\'s alone; blank, as the stair\'s type.': 'Ό,τι ορίζεται εδώ ισχύει μόνο για αυτή την πλευρά· κενό: όπως ο τύπος της σκάλας.',
  'The stair has no railing on this side.': 'Η σκάλα δεν έχει κιγκλίδωμα σε αυτή την πλευρά.',
  'Put it back': 'Επαναφορά',
  'as one climbs': 'κατά την άνοδο',
  'Balustrade': 'Κιγκλίδωμα',
  'Handrail on the wall': 'Χειρολισθήρας στον τοίχο',
  'Over the nosings, to the handrail\'s axis; blank: the type\'s': 'Πάνω από τις μύτες των βαθμίδων, έως τον άξονα του χειρολισθήρα· κενό: του τύπου',
  'Delete railing': 'Διαγραφή κιγκλιδώματος',
  'Select the stair': 'Επιλογή της σκάλας',
  'Click a railing in a plan or in 3D to select it on its own: its height, its kind, or Delete.': 'Κάντε κλικ σε ένα κιγκλίδωμα σε κάτοψη ή σε 3D για να το επιλέξετε μόνο του: το ύψος του, το είδος του ή Delete.',
