  'The first flight\'s foot on a footing of its own, a strip under its first tread, flush with the first riser (exported as an IfcFooting)': 'Το πόδι της πρώτης ράμπας σε δικό του θεμέλιο, μια λωρίδα κάτω από την πρώτη βαθμίδα, στο ίδιο επίπεδο με το πρώτο ύψος βαθμίδας (εξάγεται ως IfcFooting)',
  'Detail callout': 'Παραπομπή λεπτομέρειας',
