  'A detail of an area of this view: a new view cropped to it at a larger scale, marked here with its number and sheet': 'Μια λεπτομέρεια μιας περιοχής αυτής της προβολής: μια νέα προβολή περικομμένη σε αυτήν, σε μεγαλύτερη κλίμακα, σημειωμένη εδώ με τον αριθμό και το φύλλο της',
  'The detail view\'s scale; auto: 1:20, or the project\'s next standard scale under this view\'s': 'Η κλίμακα της προβολής λεπτομέρειας· αυτόματη: 1:20 ή η επόμενη τυπική κλίμακα του έργου κάτω από αυτήν της προβολής',
  'auto scale': 'αυτόματη κλίμακα',
  'A view that is there already (a drafting view, another detail): the callout points at it and makes none': 'Μια προβολή που υπάρχει ήδη (προβολή σχεδίασης, άλλη λεπτομέρεια): η παραπομπή δείχνει σε αυτήν και δεν δημιουργεί καμία',
  'a new detail view': 'μια νέα προβολή λεπτομέρειας',
  'The callout refers to the view chosen: double-click it to open that view.': 'Η παραπομπή παραπέμπει στην επιλεγμένη προβολή: κάντε διπλό κλικ για να την ανοίξετε.',
  'The detail view is made: double-click the callout to open it.': 'Η προβολή λεπτομέρειας δημιουργήθηκε: κάντε διπλό κλικ στην παραπομπή για να την ανοίξετε.',
  'Drag: move the callout': 'Σύρετε: μετακίνηση της παραπομπής',
