  'Drag: move the head': 'Σύρετε: μετακίνηση της κεφαλής',
  'Open view': 'Άνοιγμα προβολής',
  'The view this callout calls is gone.': 'Η προβολή στην οποία παραπέμπει αυτή η παραπομπή δεν υπάρχει πια.',
  'The detail view the callout made': 'Η προβολή λεπτομέρειας που δημιούργησε η παραπομπή',
