  'Point the callout at a view that is there instead (the detail view it made stays)': 'Παραπέμψτε την παραπομπή σε μια προβολή που υπάρχει ήδη (η προβολή λεπτομέρειας που δημιούργησε παραμένει)',
  'Refer to': 'Παραπομπή σε',
  'Its own detail view': 'Η δική της προβολή λεπτομέρειας',
