  'Its detail view': 'Η προβολή λεπτομέρειάς της',
  'Keep it': 'Διατήρηση',
  'Delete it too': 'Διαγραφή και αυτής',
  'The host runs another version of Lapin: update Lapin (Help → Check for updates) and join again.': 'Ο διακομιστής χρησιμοποιεί άλλη έκδοση του Lapin: ενημερώστε το Lapin (Βοήθεια → Έλεγχος για ενημερώσεις) και συνδεθείτε ξανά.',
  'A frame from the session could not be read; the session goes on.': 'Δεν ήταν δυνατή η ανάγνωση ενός πλαισίου από τη συνεδρία· η συνεδρία συνεχίζεται.',
  'A call to the session could not be sent.': 'Δεν ήταν δυνατή η αποστολή μιας κλήσης προς τη συνεδρία.',
  'Still working on the last edit…': 'Συνεχίζεται η επεξεργασία της τελευταίας αλλαγής…',
  'Layer extents': 'Προεκτάσεις στρώσεων',
  'Add a layer extent': 'Προσθήκη προέκτασης στρώσης',
  'How far the layer goes past this edge (positive) or stops short of it (negative)': 'Πόσο προχωρά η στρώση πέρα από αυτή την ακμή (θετικό) ή πόσο σταματά πριν από αυτήν (αρνητικό)',
  'Whether the layer past the edge cuts the walls and floors it meets; off, it overlaps them': 'Αν η στρώση πέρα από την ακμή κόβει τους τοίχους και τις πλάκες που συναντά· απενεργοποιημένο, τους επικαλύπτει',
  'Every layer ends at the element\'s edges.': 'Κάθε στρώση τελειώνει στις ακμές του στοιχείου.',
  'Take the extent away': 'Αφαίρεση της προέκτασης',
  'Which edge of the outline, numbered from its first corner': 'Ποια ακμή του περιγράμματος, αριθμημένη από την πρώτη γωνία του',
  'Cuts others': 'Κόβει τα άλλα',
  'Layer extent': 'Προέκταση στρώσης',
  'Clear layer extents': 'Εκκαθάριση προεκτάσεων στρώσεων',
  'Walls and floors': 'Τοίχοι και πλάκες',
  'Edit layers': 'Επεξεργασία στρώσεων',
  'Select a wall or a floor: its layers show a grip on each edge, in plans and sections.': 'Επιλέξτε έναν τοίχο ή μια πλάκα: οι στρώσεις του δείχνουν μια λαβή σε κάθε ακμή, σε κατόψεις και τομές.',
  'What the layer past the edge does where it meets another element: overlaps it, cuts it, or cuts it only where its element comes first in the cut order': 'Τι κάνει η στρώση πέρα από την ακμή εκεί που συναντά άλλο στοιχείο: το επικαλύπτει, το κόβει, ή το κόβει μόνο όπου το στοιχείο της έρχεται πρώτο στη σειρά κοπής',
