  'A number; lengths in metres, angles in degrees.': 'Ένας αριθμός· μήκη σε μέτρα, γωνίες σε μοίρες.',
  'The elements picked in the model when the node was set; those deleted since are left out.': 'Τα στοιχεία που επιλέχθηκαν στο μοντέλο όταν ορίστηκε ο κόμβος· όσα διαγράφηκαν από τότε παραλείπονται.',
  'A storey of the project; none chosen: the view\'s.': 'Ένας όροφος του έργου· αν δεν επιλεγεί κανένας: της προβολής.',
  'From start to end (both in), a step apart.': 'Από την αρχή έως το τέλος (και τα δύο μέσα), με ένα βήμα απόσταση.',
  'An item by its place, from 0; a negative index counts from the end.': 'Ένα στοιχείο κατά τη θέση του, από το 0· αρνητικός δείκτης μετράει από το τέλος.',
  'The items whose Keep is yes; Keep shorter than the list repeats its last.': 'Τα στοιχεία των οποίων το Keep είναι ναι· ένα Keep πιο σύντομο από τη λίστα επαναλαμβάνει την τελευταία του τιμή.',
  'A formula of a, b, c and d (+ - * / ^, min, max, round, sqrt, sin, cos, if…; angles in degrees).': 'Ένας τύπος των a, b, c και d (+ - * / ^, min, max, round, sqrt, sin, cos, if…· γωνίες σε μοίρες).',
  'The points dividing a line into equal parts, both ends included.': 'Τα σημεία που χωρίζουν μια γραμμή σε ίσα μέρη, με τα δύο άκρα.',
  'Row by row, from the origin.': 'Γραμμή προς γραμμή, από την αρχή.',
  'A polyline\'s points, and the starts and ends of its segments (to draw a wall on each).': 'Τα σημεία μιας πολυγραμμής και οι αρχές και τα τέλη των τμημάτων της (για να σχεδιάσετε έναν τοίχο σε καθένα).',
  'Every element of a class (IfcWall, IfcSlab…) in the model as it is.': 'Κάθε στοιχείο μιας κλάσης (IfcWall, IfcSlab…) στο μοντέλο όπως είναι.',
  'An element\'s attribute by its key (height, thickness…), or its name, class or id.': 'Ένα χαρακτηριστικό στοιχείου με το κλειδί του (height, thickness…), ή το όνομα, η κλάση ή το id του.',
  'Shows what it is given.': 'Εμφανίζει ό,τι δέχεται.',
