  'Floors on a stack of storeys, each turned a little more than the one below, with columns; sliders for floors, height, twist, width and taper.': 'Πλάκες σε στοίβα ορόφων, καθεμία στραμμένη λίγο περισσότερο από την από κάτω, με υποστυλώματα· ρυθμιστικά για τους ορόφους, το ύψος, τη συστροφή, το πλάτος και τη στένωση.',
  'Columns on a grid': 'Υποστυλώματα σε κάναβο',
  'A column at each point of a grid: how many each way, and the spacing.': 'Ένα υποστύλωμα σε κάθε σημείο ενός κανάβου: πόσα προς κάθε κατεύθυνση και η απόσταση.',
  'Walls round a rectangle': 'Τοίχοι γύρω από ορθογώνιο',
  'Four walls round a rectangle of the width and depth you set.': 'Τέσσερις τοίχοι γύρω από ένα ορθογώνιο με το πλάτος και το βάθος που ορίζετε.',
  'A graph wires nodes (numbers, points, lists, the commands of the tools) into a recipe: Lapin shows what it would make as a ghost, and Bake makes it.': 'Ένα γράφημα συνδέει κόμβους (αριθμούς, σημεία, λίστες, τις εντολές των εργαλείων) σε μια συνταγή: το Lapin δείχνει ως φάντασμα τι θα δημιουργούσε και το Οριστικοποίηση το δημιουργεί.',
