  'The Script panel is a developer extra: turn on Developer extras in Preferences (File → Preferences…, General).': 'Ο πίνακας Script είναι πρόσθετο για προγραμματιστές: ενεργοποιήστε τα Πρόσθετα για προγραμματιστές στις Προτιμήσεις (Αρχείο → Προτιμήσεις…, Γενικά).',
