  'Drag to resize': 'Σύρετε για αλλαγή μεγέθους',
  'Lapin for the desktop runs your own Python (3.11 or newer) in the Script panel; in the browser there is none.': 'Το Lapin για desktop εκτελεί τη δική σας Python (3.11 ή νεότερη) στον πίνακα Script· στο πρόγραμμα περιήγησης δεν υπάρχει.',
  'Python in Lapin: a console and an editor that run your own Python (3.11 or newer) with the lapinbim package; each Run is one undo step. A developer extra.': 'Python στο Lapin: μια κονσόλα και ένας επεξεργαστής που εκτελούν τη δική σας Python (3.11 ή νεότερη) με το πακέτο lapinbim· κάθε Εκτέλεση είναι ένα βήμα αναίρεσης. Πρόσθετο για προγραμματιστές.',
  'Python console': 'Κονσόλα Python',
