  'Save the recorded script in Mine and open it in the editor': 'Αποθήκευση του καταγραμμένου script στα Δικά μου και άνοιγμά του στον επεξεργαστή',
  'A command on the window\'s selection is written lapin.selection(), so the script works on what is selected when it runs': 'Μια εντολή πάνω στην επιλογή του παραθύρου γράφεται lapin.selection(), ώστε το script να δουλεύει σε ό,τι είναι επιλεγμένο όταν εκτελείται',
  'Selection as lapin.selection()': 'Η επιλογή ως lapin.selection()',
  'Clear the recording': 'Εκκαθάριση της καταγραφής',
  'Recording: draw, change or delete something in the window.': 'Γίνεται καταγραφή: σχεδιάστε, αλλάξτε ή διαγράψτε κάτι στο παράθυρο.',
  'Record, then work in the window: each step shows here as a line of Python, ready to run on another project.': 'Καταγράψτε και μετά δουλέψτε στο παράθυρο: κάθε βήμα εμφανίζεται εδώ ως γραμμή Python, έτοιμη να εκτελεστεί σε άλλο έργο.',
  'The recorded script is copied.': 'Το καταγραμμένο script αντιγράφηκε.',
