  'A script can do anything you can do on this computer: run it only if you know where it comes from. Trust remembers this code on this computer; a change to it asks again.': 'Ένα script μπορεί να κάνει ό,τι μπορείτε να κάνετε εσείς σε αυτόν τον υπολογιστή: εκτελέστε το μόνο αν γνωρίζετε από πού προέρχεται. Η εμπιστοσύνη θυμάται αυτόν τον κώδικα σε αυτόν τον υπολογιστή· μια αλλαγή σε αυτόν ρωτά ξανά.',
