  'Run script': 'Εκτέλεση script',
  'Scripts': 'Scripts',
  'The script of this tool is gone.': 'Το script αυτού του εργαλείου δεν υπάρχει πια.',
  'Nothing selected': 'Τίποτα επιλεγμένο',
