  'The session closed: the host stopped sharing, quit Lapin or lost the connection.': 'Η συνεδρία έκλεισε: ο διοργανωτής διέκοψε την κοινή χρήση, έκλεισε το Lapin ή έχασε τη σύνδεση.',
