  'The model cut above the highest storey shown, this far over its level, as a plan cuts it': 'Το μοντέλο τεμνόμενο πάνω από τον ψηλότερο εμφανιζόμενο όροφο, τόσο πάνω από τη στάθμη του, όπως το τέμνει μια κάτοψη',
  'The 3D follows the active storey: pick another level in the project browser.': 'Το 3D ακολουθεί τον ενεργό όροφο: επιλέξτε άλλη στάθμη στον περιηγητή έργου.',
  'Which storeys this 3D view shows: View → Storeys shown, or its properties': 'Ποιους ορόφους εμφανίζει αυτή η προβολή 3D: Προβολή → Εμφανιζόμενοι όροφοι ή οι ιδιότητές της',
