  'Which layers of walls, floors and footings the 3D view shows (each kept layer a solid of its own); the finishes are the layers of materials whose category is Finish': 'Ποιες στρώσεις τοίχων, πλακών και θεμελίων εμφανίζει η προβολή 3D (κάθε στρώση που διατηρείται είναι ξεχωριστό στερεό)· τα φινιρίσματα είναι οι στρώσεις υλικών με κατηγορία Finish',
