  'Not here, only in the desktop app: the AI bridge (MCP) and views in windows of their own. A large imported IFC file may not fit in the browser.': 'Δεν είναι διαθέσιμο εδώ, μόνο στην εφαρμογή επιφάνειας εργασίας: η γέφυρα AI (MCP) και οι όψεις σε ξεχωριστά παράθυρα. Ένα μεγάλο εισαγόμενο αρχείο IFC μπορεί να μη χωράει στο πρόγραμμα περιήγησης.',
