  'On (the default): its elements join where they meet others (walls at a corner, a beam into a column, one hatch where one material goes on). Off: they keep their shape (steel, timber): not joined, not cut by the cut order nor cutting others, their own outline drawn.': 'Ενεργό (προεπιλογή): τα στοιχεία του συνδέονται εκεί που συναντούν άλλα (τοίχοι στη γωνία, δοκός σε υποστύλωμα, μία διαγράμμιση εκεί που συνεχίζει ένα υλικό). Ανενεργό: διατηρούν το σχήμα τους (χάλυβας, ξύλο): χωρίς σύνδεση, δεν κόβονται από τη σειρά κοπής ούτε κόβουν άλλα, σχεδιάζεται το δικό τους περίγραμμα.',
