  'Projected: the pieces parallel to the first cut the model and the jogs cut nothing, all drawn in one frame, so grids stand where they cross in plan. Developed: every piece cuts and is drawn beside the previous at its length': 'Προβαλλόμενη: τα τμήματα παράλληλα προς την πρώτη τέμνουν το μοντέλο και οι αναβαθμοί δεν τέμνουν τίποτα, όλα σχεδιασμένα σε ένα πλαίσιο, ώστε οι άξονες να βρίσκονται εκεί που τέμνονται στην κάτοψη. Αναπτυγμένη: κάθε τμήμα τέμνει και σχεδιάζεται δίπλα στο προηγούμενο με το μήκος του',
  'The section follows the element\'s line as it is now; stop following to keep the line as it is and edit it': 'Η τομή ακολουθεί τη γραμμή του στοιχείου όπως είναι τώρα· διακόψτε την παρακολούθηση για να κρατήσετε τη γραμμή όπως είναι και να την επεξεργαστείτε',
