  'Delete stored files: the files leave the project file at the next save; the record, the names and the hashes stay': 'Διαγραφή αποθηκευμένων αρχείων: τα αρχεία φεύγουν από το αρχείο του έργου στην επόμενη αποθήκευση· η εγγραφή, τα ονόματα και τα hash μένουν',
  'Publish to another folder…': 'Δημοσίευση σε άλλο φάκελο…',
  'The IFC is kept in the project file only when asked; its name and hash are recorded': 'Το IFC κρατιέται στο αρχείο του έργου μόνο όταν ζητηθεί· καταγράφονται το όνομα και το hash του',
