  'No remark yet. New remark makes one from the 3D view; Import BCF… reads a reviewer\'s file.': 'Δεν υπάρχει ακόμη παρατήρηση. Η Νέα παρατήρηση δημιουργεί μία από την τρισδιάστατη προβολή· η Εισαγωγή BCF… διαβάζει το αρχείο ενός ελεγκτή.',
