  'Remarks on sheets': 'Παρατηρήσεις σε φύλλα',
  'What a reviewer marked on an issued PDF — notes, text, highlights, pen, shapes, clouds, stamps — read back onto the sheet, at its place, with who and when. Reading the same file again updates its remarks. They show over the sheet on screen only; a sheet prints without them.': 'Ό,τι σημείωσε ένας ελεγκτής σε ένα εκδοθέν PDF — σημειώσεις, κείμενο, επισημάνσεις, στυλό, σχήματα, νέφη, σφραγίδες — διαβάζεται πίσω στο φύλλο, στη θέση του, με το ποιος και πότε. Η ανάγνωση του ίδιου αρχείου ξανά ενημερώνει τις παρατηρήσεις του. Φαίνονται πάνω στο φύλλο μόνο στην οθόνη· το φύλλο εκτυπώνεται χωρίς αυτές.',
