  'Select what to array first, then Array.': 'Επιλέξτε πρώτα τι θα αντιγραφεί σε διάταξη, και μετά Διάταξη.',
  'Elements are arrayed in a plan or in 3D: here only the drafted shapes, texts and symbols were arrayed.': 'Τα στοιχεία αντιγράφονται σε διάταξη σε κάτοψη ή σε 3D: εδώ αντιγράφηκαν μόνο τα σχεδιασμένα σχήματα, κείμενα και σύμβολα.',
  'Drafted shapes are arrayed in their own view (a plan, a section, an elevation or a drafting view): only the elements were arrayed.': 'Τα σχεδιασμένα σχήματα αντιγράφονται στη δική τους προβολή (κάτοψη, τομή, όψη ή προβολή σχεδίασης): αντιγράφηκαν μόνο τα στοιχεία.',
  'Dimensions and tags measure or name their elements: they were left out of the array.': 'Οι διαστάσεις και οι ετικέτες μετρούν ή ονομάζουν τα στοιχεία τους: έμειναν εκτός της διάταξης.',
  'Select what to array first, then Polar array.': 'Επιλέξτε πρώτα τι θα αντιγραφεί σε διάταξη, και μετά Πολική διάταξη.',
