  'Pinned': 'Καρφιτσωμένο',
  'A pinned element stays where it is: it is not moved, turned, mirrored, sent to another storey nor deleted until it is unpinned. Its other fields still change': 'Ένα καρφιτσωμένο στοιχείο μένει εκεί που είναι: δεν μετακινείται, δεν περιστρέφεται, δεν καθρεφτίζεται, δεν στέλνεται σε άλλον όροφο ούτε διαγράφεται μέχρι να ξεκαρφιτσωθεί. Τα υπόλοιπα πεδία του αλλάζουν κανονικά',
  'Pinned: unpin it to delete it': 'Καρφιτσωμένο: ξεκαρφιτσώστε το για να το διαγράψετε',
  'Select what to pin first.': 'Επιλέξτε πρώτα τι θα καρφιτσώσετε.',
  'Select what to unpin first.': 'Επιλέξτε πρώτα τι θα ξεκαρφιτσώσετε.',
  'Elements turn in a plan or in 3D: in a section or an elevation a turn would tip them over (drafted shapes turn here).': 'Τα στοιχεία περιστρέφονται σε κάτοψη ή σε 3D: σε τομή ή όψη μια περιστροφή θα τα ανέτρεπε (τα σχεδιασμένα σχήματα περιστρέφονται εδώ).',
  'In a section or an elevation, elements mirror about a vertical line (across the plane through it, square to the view).': 'Σε τομή ή όψη, τα στοιχεία καθρεφτίζονται ως προς κατακόρυφη γραμμή (πάνω από το επίπεδο που διέρχεται από αυτήν, κάθετα στην προβολή).',
