  'What is done to it after its operation, in order: each redone when the sketch changes': 'Τι γίνεται σε αυτό μετά τη λειτουργία του, με τη σειρά: κάθε βήμα επαναλαμβάνεται όταν αλλάζει το σκίτσο',
