  'Type a length: the side\'s end moves along it, the sides after it follow up to the next one running the same way': 'Πληκτρολογήστε ένα μήκος: το άκρο της πλευράς κινείται κατά μήκος του, οι επόμενες πλευρές το ακολουθούν έως την επόμενη που έχει την ίδια κατεύθυνση',
  'Pick the face in a 3D view: Studio works on the faces the body has.': 'Επιλέξτε την έδρα σε προβολή 3D: το Studio δουλεύει στις έδρες που έχει το σώμα.',
  'The extrusion is deeper or shallower: its depth changed.': 'Η εξώθηση είναι βαθύτερη ή ρηχότερη: το βάθος της άλλαξε.',
  'The side moved: the sketch\'s edge under it went with it.': 'Η πλευρά μετακινήθηκε: η ακμή του σκίτσου από κάτω της ακολούθησε.',
  'Done as a step of the solid: it is in its Studio steps, and redone when the sketch changes.': 'Έγινε ως βήμα του στερεού: βρίσκεται στα βήματα Studio του και επαναλαμβάνεται όταν αλλάζει το σκίτσο.',
  'A solid stands on the face, in its material: edit its distance in its properties.': 'Ένα στερεό στέκεται πάνω στην έδρα, με το υλικό της: επεξεργαστείτε την απόστασή του στις ιδιότητές του.',
  'The face is pushed in: a cut the element is less, kept live.': 'Η έδρα ωθείται προς τα μέσα: μια τομή αφαιρείται από το στοιχείο, πάντα ενημερωμένη.',
  'Pushed or pulled.': 'Ώθηση ή έλξη.',
  'Chamfers and fillets go on Studio solids: make the element one first (Make Studio solid).': 'Οι λοξοτομές και οι στρογγυλεύσεις γίνονται σε στερεά Studio: κάντε πρώτα το στοιχείο στερεό (Δημιουργία στερεού Studio).',
  'Select the Studio solid first, then pick the face whose plane cuts it (a face of the solid itself, or of any element).': 'Επιλέξτε πρώτα το στερεό Studio και μετά την έδρα της οποίας το επίπεδο το τέμνει (έδρα του ίδιου του στερεού ή οποιουδήποτε στοιχείου).',
  'There is no flat face there.': 'Δεν υπάρχει επίπεδη έδρα εκεί.',
