  'Close the shape': 'Κλείσιμο του σχήματος',
  'A solid stands on the face, from the shape drawn on it: Push/Pull its end, or change the sketch, and it follows.': 'Ένα στερεό στέκεται πάνω στην έδρα, από το σχήμα που σχεδιάστηκε σε αυτήν: ωθήστε/έλξτε το άκρο του ή αλλάξτε το σκίτσο και το ακολουθεί.',
  'Cut into the face, from the shape drawn on it: Push/Pull the pocket\'s floor to make it deeper or shallower.': 'Κοπή μέσα στην έδρα, από το σχήμα που σχεδιάστηκε σε αυτήν: ωθήστε/έλξτε τον πυθμένα της υποδοχής για να γίνει βαθύτερη ή ρηχότερη.',
  'The shape stays on the face as a sketch: extrude it later, or draw over it.': 'Το σχήμα μένει στην έδρα ως σκίτσο: εξωθήστε το αργότερα ή σχεδιάστε πάνω του.',
