  'Drag an arrow or type a distance · Tab: next axis · Enter applies · Esc cancels': 'Σύρετε ένα βέλος ή πληκτρολογήστε απόσταση · Tab: επόμενος άξονας · Enter εφαρμόζει · Esc ακυρώνει',
  'Split in two: both keep the sketch, so changing it changes both.': 'Χωρίστηκε σε δύο: και τα δύο κρατούν το σκίτσο, οπότε αν το αλλάξετε αλλάζουν και τα δύο.',
  'Select the Studio solid first, then pick the face it is mirrored in.': 'Επιλέξτε πρώτα το στερεό Studio και μετά την έδρα ως προς την οποία καθρεφτίζεται.',
  'Select the elements to make into Studio solids (a reference from IFC, an imported mesh, a wall…).': 'Επιλέξτε τα στοιχεία που θα γίνουν στερεά Studio (αναφορά από IFC, εισαγόμενο πλέγμα, τοίχος…).',
