  'Far parts drawn coarser, up to 3 pixels off: for large models and slower computers.': 'Τα απομακρυσμένα τμήματα σχεδιάζονται πιο χονδρικά, με απόκλιση έως 3 pixel: για μεγάλα μοντέλα και πιο αργούς υπολογιστές.',
  'Far parts drawn coarser where the difference is under a pixel.': 'Τα απομακρυσμένα τμήματα σχεδιάζονται πιο χονδρικά εκεί όπου η διαφορά είναι κάτω από ένα pixel.',
  'Every part drawn as it is, near or far.': 'Κάθε τμήμα σχεδιάζεται όπως είναι, κοντά ή μακριά.',
  'How the 3D view draws parts of many triangles (an imported plant, furniture, pipes) when they are far away. The model, its drawings, exports and quantities keep their full precision.': 'Πώς σχεδιάζει η προβολή 3D τα τμήματα με πολλά τρίγωνα (εισαγόμενη εγκατάσταση, έπιπλα, σωλήνες) όταν είναι μακριά. Το μοντέλο, τα σχέδιά του, οι εξαγωγές και οι ποσότητες διατηρούν πλήρη ακρίβεια.',
