  'The browser files the view under this discipline\'s set; a view takes its discipline\'s style': 'Ο περιηγητής τοποθετεί την προβολή στο σύνολο αυτής της ειδικότητας· η προβολή παίρνει το στυλ της ειδικότητάς της',
  'The discipline (the browser groups views and sheets by it)': 'Η ειδικότητα (ο περιηγητής ομαδοποιεί προβολές και φύλλα με βάση αυτήν)',
  'Surfaces for rendering, visualisation and AR: each element a node with its GlobalId, IFC class and type, a mesh per material. To exchange the model itself, use Export IFC.': 'Επιφάνειες για απόδοση, οπτικοποίηση και AR: κάθε στοιχείο ένας κόμβος με το GlobalId, την κλάση IFC και τον τύπο του, ένα πλέγμα ανά υλικό. Για ανταλλαγή του ίδιου του μοντέλου, χρησιμοποιήστε Εξαγωγή IFC.',
  'The elements\' edges as lines, besides their faces; most programs do not use them': 'Οι ακμές των στοιχείων ως γραμμές, εκτός από τις έδρες· τα περισσότερα προγράμματα δεν τις χρησιμοποιούν',
  'Halftone': 'Halftone',
  '(no path)': '(χωρίς διαδρομή)',
  'What a link brought cannot be edited or deleted on its own: unlink it, convert it, or open it on its own.': 'Ό,τι έφερε μια σύνδεση δεν μπορεί να επεξεργαστεί ή να διαγραφεί μεμονωμένα: αποσυνδέστε την, μετατρέψτε την ή ανοίξτε την ξεχωριστά.',
  'Drawn in every view': 'Σχεδιάζεται σε κάθε προβολή',
