  'Forget this file (projects keep what they use)': 'Λήθη αυτού του αρχείου (τα έργα κρατούν ό,τι χρησιμοποιούν)',
  'What the material is in a layered element (IfcMaterial.Category). A view style without finishes leaves out the layers of finish materials; without a category, plaster, render, paint, tiles, boards and floor coverings count as finishes.': 'Τι είναι το υλικό σε ένα πολυστρωματικό στοιχείο (IfcMaterial.Category). Ένα στυλ προβολής χωρίς φινιρίσματα παραλείπει τις στρώσεις υλικών φινιρίσματος· χωρίς κατηγορία, το σοβάτισμα, το χρώμα, τα πλακίδια, οι πλάκες και τα δάπεδα μετρούν ως φινιρίσματα.',
  'Off (the default): where this material goes on from one element into another (two walls\' cores, footings round a corner) no line is drawn between them. On: the joint is drawn.': 'Ανενεργό (προεπιλογή): όπου αυτό το υλικό συνεχίζεται από ένα στοιχείο σε άλλο (οι πυρήνες δύο τοίχων, θεμέλια σε γωνία) δεν σχεδιάζεται γραμμή ανάμεσά τους. Ενεργό: ο αρμός σχεδιάζεται.',
  'Where the hatch starts and turns: from the view\'s origin, or from each band it fills (along the band\'s longest edge)': 'Πού ξεκινά και πώς στρέφεται η διαγράμμιση: από την αρχή της προβολής ή από κάθε ζώνη που γεμίζει (κατά μήκος της μακρύτερης ακμής της)',
