  'Above the cut, up to Top: dashed (overhead). From the cut down to Bottom: drawn. Below Bottom, down to the depth: faint (beyond).': 'Πάνω από την τομή, έως το Πάνω: διακεκομμένα (από πάνω). Από την τομή προς τα κάτω έως το Κάτω: σχεδιασμένα. Κάτω από το Κάτω, έως το βάθος: αχνά (πέρα).',
