  'Back to the style\'s': 'Επιστροφή σε αυτό του στυλ',
  'The browser files the view under this discipline\'s set; without a style of its own the view draws as the discipline\'s style says': 'Ο περιηγητής τοποθετεί την προβολή στο σύνολο αυτής της ειδικότητας· χωρίς δικό της στυλ η προβολή σχεδιάζεται όπως λέει το στυλ της ειδικότητας',
  'The style gives every setting below; what the view sets itself wins over it': 'Το στυλ δίνει κάθε ρύθμιση παρακάτω· ό,τι ορίζει η ίδια η προβολή υπερισχύει',
  'One material goes on from one element into the next without a line (walls, beams, footings): on by default': 'Ένα υλικό συνεχίζεται από στοιχείο σε στοιχείο χωρίς γραμμή (τοίχοι, δοκοί, θεμέλια): ενεργό από προεπιλογή',
  'What lies above the cut plane, up to the range\'s top, drawn dashed': 'Ό,τι βρίσκεται πάνω από το επίπεδο τομής, έως την κορυφή του εύρους, σχεδιασμένο διακεκομμένο',
  'From above: a plan. From below: a reflected ceiling plan, what lies above the cut up to the range\'s top (soffits, beams, formwork), drawn the way the plan lies': 'Από πάνω: κάτοψη. Από κάτω: κάτοψη ανεστραμμένης οροφής, ό,τι βρίσκεται πάνω από την τομή έως την κορυφή του εύρους (οροφές, δοκοί, ξυλότυποι), σχεδιασμένο όπως στέκεται η κάτοψη',
  'Another level\'s plan drawn under this one on screen, faded, never picked but snapped to; it does not print': 'Η κάτοψη άλλου επιπέδου σχεδιασμένη κάτω από αυτήν στην οθόνη, ξεθωριασμένη, δεν επιλέγεται ποτέ αλλά έχει snap· δεν εκτυπώνεται',
  'What this view shows and how, by category, class and element (VV)': 'Τι εμφανίζει αυτή η προβολή και πώς, ανά κατηγορία, κλάση και στοιχείο (VV)',
