  'Each vertex is a point of intersection (PI): the arc of its radius is fitted between the two straights, with a clothoid of the length given before and after it. The arc and both clothoids must fit on the straights to the neighbouring vertices, else the engine refuses the curve and says why.': 'Κάθε κορυφή είναι ένα σημείο τομής (PI): το τόξο της ακτίνας του προσαρμόζεται ανάμεσα στις δύο ευθείες, με κλωθοειδή του δοθέντος μήκους πριν και μετά. Το τόξο και οι δύο κλωθοειδείς πρέπει να χωρούν στις ευθείες έως τις γειτονικές κορυφές, αλλιώς η μηχανή απορρίπτει την καμπύλη και εξηγεί γιατί.',
  'On a track the arcs are the cant\'s curves: design the cant in the inspector once the radii are set.': 'Σε μια γραμμή τα τόξα είναι οι καμπύλες της υπερύψωσης: σχεδιάστε την υπερύψωση στον επιθεωρητή αφού οριστούν οι ακτίνες.',
