  'Entry and mudroom': 'Είσοδος και αποθήκη παπουτσιών',
  'Toddler playhouse': 'Παιδικό σπιτάκι',
  'Dog bed house': 'Σπιτάκι σκύλου',
  'Cupboard doors on the open side, shelves behind them, open shelves at the high end': 'Θύρες ντουλαπιού στην ανοιχτή πλευρά, ράφια πίσω τους, ανοιχτά ράφια στο ψηλό άκρο',
  'A desk at the high end with a shelf and a light over it, cupboards in the low part': 'Ένα γραφείο στο ψηλό άκρο με ράφι και φωτιστικό πάνω του, ντουλάπια στο χαμηλό τμήμα',
  'A bench with a cushion and back cushions, a bookcase at the high end, a reading light': 'Ένα παγκάκι με μαξιλάρι και μαξιλάρια πλάτης, μια βιβλιοθήκη στο ψηλό άκρο, ένα φωτιστικό ανάγνωσης',
  'A bench with cubbies for shoes under it and coat hooks over it, the low part closed': 'Ένα παγκάκι με θήκες για παπούτσια από κάτω και κρεμάστρες από πάνω, το χαμηλό τμήμα κλειστό',
  'A closed front with a small door and a window, a play mat inside': 'Ένα κλειστό μέτωπο με μικρή θύρα και παράθυρο, ένα χαλάκι παιχνιδιού μέσα',
  'A closed front with a framed opening and a dog\'s bed behind it': 'Ένα κλειστό μέτωπο με πλαισιωμένο άνοιγμα και ένα κρεβάτι σκύλου πίσω του',
  'The bookcase does not fit: the space is too short.': 'Η βιβλιοθήκη δεν χωράει: ο χώρος είναι πολύ κοντός.',
  'The desk does not fit under the slope here: it is left out.': 'Το γραφείο δεν χωράει κάτω από την κλίση εδώ: παραλείπεται.',
  'The bench does not fit under the slope here: it is left out.': 'Το παγκάκι δεν χωράει κάτω από την κλίση εδώ: παραλείπεται.',
  'The mudroom bench does not fit under the slope here: it is left out.': 'Το παγκάκι εισόδου δεν χωράει κάτω από την κλίση εδώ: παραλείπεται.',
  'The playhouse door does not fit under the slope here: it is left out.': 'Η θύρα του παιδικού σπιτιού δεν χωράει κάτω από την κλίση εδώ: παραλείπεται.',
  'The dog\'s opening does not fit under the slope here: it is left out.': 'Το άνοιγμα του σκύλου δεν χωράει κάτω από την κλίση εδώ: παραλείπεται.',
  'The coat hooks do not fit under the slope here: they are left out.': 'Οι κρεμάστρες δεν χωράνε κάτω από την κλίση εδώ: παραλείπονται.',
  'The window does not fit beside the door: it is left out.': 'Το παράθυρο δεν χωράει δίπλα στη θύρα: παραλείπεται.',
  'Only a stair with straight flights has a space under it to furnish.': 'Μόνο μια σκάλα με ευθύγραμμα σκέλη έχει χώρο από κάτω για διαμόρφωση.',
  'The stair is solid down to the floor: there is no space under it.': 'Η σκάλα είναι συμπαγής μέχρι το δάπεδο: δεν υπάρχει χώρος από κάτω.',
  'The flight has no treads to go under.': 'Το σκέλος δεν έχει πατήματα για να μπει κάτω από αυτά.',
  'The space under the flight is too low or too short to furnish (less than 300 mm).': 'Ο χώρος κάτω από το σκέλος είναι πολύ χαμηλός ή πολύ κοντός για διαμόρφωση (λιγότερο από 300 mm).',
  'The stair stands on no storey.': 'Η σκάλα δεν βρίσκεται σε κανέναν όροφο.',
