  'Quantity takeoff made: it is in the project browser, under Schedules, and goes on a sheet like a view.': 'Η προμέτρηση δημιουργήθηκε: βρίσκεται στον περιηγητή έργου, στους Πίνακες, και μπαίνει σε φύλλο όπως μια όψη.',
