  'Load-bearing walls, floors and roofs': 'Φέροντες τοίχοι, δάπεδα και στέγες',
  'cut them too (else reported, not cut)': 'να κόβονται κι αυτοί (αλλιώς αναφέρονται, δεν κόβονται)',
  'A system may say otherwise: MEP → Systems….': 'Ένα σύστημα μπορεί να ορίζει διαφορετικά: Η/Μ → Συστήματα….',
  'Whether its runs cut their own openings in the walls, floors and roofs they cross (Manage → Cut order)': 'Αν οι διαδρομές του ανοίγουν δικά τους ανοίγματα στους τοίχους, τα δάπεδα και τις στέγες που διασχίζουν (Διαχείριση → Σειρά κοπής)',
