  'Corners (mm)': 'Γωνίες (mm)',
  'Each corner u v in millimetres (u across, v up), a semicolon between; a third number makes the side from that corner an arc (its bulge: 1 a half circle, negative the other way)': 'Κάθε γωνία u v σε χιλιοστά (u οριζόντια, v προς τα πάνω), με ερωτηματικό ανάμεσα· ένας τρίτος αριθμός κάνει την πλευρά από εκείνη τη γωνία τόξο (η καμπύλωσή του: 1 ημικύκλιο, αρνητικός προς την άλλη πλευρά)',
  'Insertion point u': 'Σημείο εισαγωγής u',
  'Insertion point v': 'Σημείο εισαγωγής v',
  'The circle is the insertion point: on the wall\'s face at the sweep\'s height (u out of the face, into the wall for a reveal), or on a footing\'s axis at its bottom (u across, to the axis\'s left).': 'Ο κύκλος είναι το σημείο εισαγωγής: στην όψη του τοίχου στο ύψος της σάρωσης (το u έξω από την όψη, προς το εσωτερικό του τοίχου για εσοχή), ή στον άξονα ενός θεμελίου στη βάση του (το u οριζόντια, αριστερά του άξονα).',
  'What uses it keeps its copy of it': 'Ό,τι το χρησιμοποιεί κρατά το δικό του αντίγραφο',
