  'In plan: the height over the wall\'s base (or under its top); in 3D the height clicked': 'Σε κάτοψη: το ύψος πάνω από τη βάση του τοίχου (ή κάτω από την κορυφή του)· σε 3D το ύψος που πατήθηκε',
