  'No price list in the project yet: Cost → Price lists… imports yours (the suggestions come from it).': 'Δεν υπάρχει ακόμη τιμολόγιο στο έργο: Κόστος → Τιμολόγια… εισάγει το δικό σας (οι προτάσεις προέρχονται από αυτό).',
  'An article on a type prices its elements; a rule on a material prices every layer of it, in any type. A layered type\'s article measures its core, so its finishes are priced by their materials. The rows ticked are applied.': 'Ένα άρθρο σε έναν τύπο τιμολογεί τα στοιχεία του· ένας κανόνας σε ένα υλικό τιμολογεί κάθε στρώση του, σε οποιονδήποτε τύπο. Το άρθρο ενός πολυστρωματικού τύπου μετρά τον πυρήνα του, ώστε τα φινιρίσματά του να τιμολογούνται από τα υλικά τους. Εφαρμόζονται οι επιλεγμένες γραμμές.',
