  'Select a table, a picture or another block of the project, or put the cursor in a repeat or a condition, to see its settings here.': 'Επιλέξτε έναν πίνακα, μια εικόνα ή άλλο μπλοκ του έργου, ή τοποθετήστε τον δρομέα σε μια επανάληψη ή μια συνθήκη, για να δείτε εδώ τις ρυθμίσεις της.',
