  'Click a face of the model: a reference plane is made on it, and the shapes go on it': 'Κάντε κλικ σε μια έδρα του μοντέλου: δημιουργείται ένα επίπεδο αναφοράς σε αυτήν και τα σχήματα τοποθετούνται σε αυτό',
