  'The lines, polylines, rectangles, circles and arcs drafted on plans and reference planes, on their planes in 3D (View → Drafts in 3D)': 'Οι γραμμές, πολύγραμμες, ορθογώνια, κύκλοι και τόξα που σχεδιάστηκαν σε κατόψεις και επίπεδα αναφοράς, στα επίπεδά τους σε 3D (Προβολή → Σχέδια σε 3D)',
