  'A class is its IFC name (IfcWall) or its label (Wall). A "not" rule takes elements out. With no rule adding elements, the set holds everything.': 'Μια κλάση είναι το όνομά της στο IFC (IfcWall) ή η ετικέτα της (Τοίχος). Ένας κανόνας «όχι» αφαιρεί στοιχεία. Χωρίς κανόνα που προσθέτει στοιχεία, το σύνολο περιέχει τα πάντα.',
  'Zoom to cursor': 'Ζουμ στον δρομέα',
  'Orbit around selection': 'Περιστροφή γύρω από την επιλογή',
  'The wheel zooms to the point under the cursor.': 'Η ροδέλα κάνει ζουμ στο σημείο κάτω από τον δρομέα.',
  'The wheel zooms to the middle of the 3D view.': 'Η ροδέλα κάνει ζουμ στο κέντρο της τρισδιάστατης προβολής.',
  'The 3D view orbits round the selection, or the point under the cursor.': 'Η τρισδιάστατη προβολή περιστρέφεται γύρω από την επιλογή, ή το σημείο κάτω από τον δρομέα.',
  'The 3D view orbits round its middle.': 'Η τρισδιάστατη προβολή περιστρέφεται γύρω από το κέντρο της.',
  'The mouse wheel zooms to the point of the model under the cursor, which stays where it is (View → Zoom to cursor); off, to the middle of the view': 'Η ροδέλα του ποντικιού κάνει ζουμ στο σημείο του μοντέλου κάτω από τον δρομέα, το οποίο μένει στη θέση του (Προβολή → Ζουμ στον δρομέα)· απενεργοποιημένο, στο κέντρο της προβολής',
  'A drag turns the view round the selection\'s middle, else round the point of the model under the cursor (View → Orbit around selection); off, round the middle of the view': 'Η μεταφορά περιστρέφει την προβολή γύρω από το κέντρο της επιλογής, αλλιώς γύρω από το σημείο του μοντέλου κάτω από τον δρομέα (Προβολή → Περιστροφή γύρω από την επιλογή)· απενεργοποιημένο, γύρω από το κέντρο της προβολής',
  'Other clashes': 'Άλλες συγκρούσεις',
