  'HTML': 'HTML',
  'The clashes as Navisworks writes its clash reports, in their groups': 'Οι συγκρούσεις όπως τις γράφει το Navisworks στις αναφορές συγκρούσεων, στις ομάδες τους',
  'One page with a picture of each open clash, framed in the 3D view': 'Μία σελίδα με εικόνα κάθε ανοιχτής σύγκρουσης, κάδρο στην τρισδιάστατη προβολή',
  'The view in front marks the open clashes with red clouds and their numbers (test.clash), on the screen only (View → Clash marks)': 'Η μπροστινή προβολή επισημαίνει τις ανοιχτές συγκρούσεις με κόκκινα νέφη και τους αριθμούς τους (test.clash), μόνο στην οθόνη (Προβολή → Επισημάνσεις συγκρούσεων)',
  'Openings for MEP: runs through walls, floors and roofs without an opening': 'Ανοίγματα για ΗΜΜ: διελεύσεις μέσα από τοίχους, πλάκες και στέγες χωρίς άνοιγμα',
  'The check of Manage → Clash check…: each MEP run through a wall, floor or roof must lie inside an opening, with its clearance. Its depth is how far it is short. Openings are made there.': 'Ο έλεγχος του Διαχείριση → Έλεγχος συγκρούσεων…: κάθε διέλευση ΗΜΜ μέσα από τοίχο, πλάκα ή στέγη πρέπει να βρίσκεται εντός ανοίγματος, με την ανοχή της. Το βάθος της είναι το πόσο υπολείπεται. Τα ανοίγματα δημιουργούνται εκεί.',
  'Optimize IFC…': 'Βελτιστοποίηση IFC…',
  'Optimize IFC': 'Βελτιστοποίηση IFC',
  'A copy of each file, cleaned and lighter. Its GlobalIds, names, property sets, quantities and relationships stay exactly as the file wrote them; only the geometry changes, and nothing is added. The original is never written.': 'Ένα αντίγραφο κάθε αρχείου, καθαρισμένο και ελαφρύτερο. Τα GlobalId, τα ονόματα, τα σύνολα ιδιοτήτων, οι ποσότητες και οι σχέσεις του μένουν ακριβώς όπως τα έγραψε το αρχείο· αλλάζει μόνο η γεωμετρία και δεν προστίθεται τίποτα. Το πρωτότυπο δεν γράφεται ποτέ.',
  'No file yet: add one or more IFC files.': 'Δεν υπάρχει ακόμη αρχείο: προσθέστε ένα ή περισσότερα αρχεία IFC.',
  'Add files…': 'Προσθήκη αρχείων…',
