  'The document\'s text, layout, inputs and style become a template; the project\'s data is filled again in each document made from it.': 'Το κείμενο, η διάταξη, οι εισαγωγές και το στυλ του εγγράφου γίνονται πρότυπο· τα δεδομένα του έργου συμπληρώνονται ξανά σε κάθε έγγραφο που δημιουργείται από αυτό.',
