  'Furniture schedule made: it is in the project browser, under Schedules.': 'Ο πίνακας επίπλων δημιουργήθηκε: βρίσκεται στον περιηγητή έργου, στους Πίνακες.',
  'Furniture by room made: it is in the project browser, under Schedules.': 'Τα έπιπλα ανά χώρο δημιουργήθηκαν: βρίσκονται στον περιηγητή έργου, στους Πίνακες.',
