  'Drag: move the tag with its knee (the leader keeps pointing where it does)': 'Σύρετε: μετακινεί την ετικέτα μαζί με το γόνατό της (η γραμμή οδηγός συνεχίζει να δείχνει εκεί που δείχνει)',
  'Drag: the leader bends here, at 30°, 45°, 60° or 90° (Shift: any angle); past the end the text goes to that side': 'Σύρετε: η γραμμή οδηγός λυγίζει εδώ, στις 30°, 45°, 60° ή 90° (Shift: οποιαδήποτε γωνία)· πέρα από το άκρο το κείμενο πηγαίνει προς εκείνη την πλευρά',
  'Straight from a box round the text, or an elbow: an oblique line to a knee, then along under the text (as the tag type says, unless the tag says its own)': 'Ευθεία από ένα πλαίσιο γύρω από το κείμενο, ή γωνιακή: μια πλάγια γραμμή προς ένα γόνατο και μετά κατά μήκος κάτω από το κείμενο (όπως ορίζει ο τύπος της ετικέτας, εκτός αν η ετικέτα ορίζει τον δικό της)',
