  'A slab on steel posts at its front corners, repeated storey over storey; glass railing.': 'Μια πλάκα σε χαλύβδινους στύλους στις μπροστινές γωνίες της, επαναλαμβανόμενη όροφο πάνω από όροφο· γυάλινο κιγκλίδωμα.',
  'A thin slab on steel brackets fixed to the wall, posts and a handrail.': 'Μια λεπτή πλάκα σε χαλύβδινα φουρούσια στερεωμένα στον τοίχο, στύλοι και χειρολισθήρας.',
  'A light slab hung from the wall above by steel tie rods at its front corners; cable railing.': 'Μια ελαφριά πλάκα κρεμασμένη από τον επάνω τοίχο με χαλύβδινες ράβδους στις μπροστινές γωνίες της· κιγκλίδωμα με καλώδια.',
