  'Recessed into the facade: the floor inside the building line, side walls and a ceiling, the railing at the face.': 'Σε εσοχή της πρόσοψης: το δάπεδο εντός της οικοδομικής γραμμής, πλευρικοί τοίχοι και οροφή, το κιγκλίδωμα στην όψη.',
