  'EN 81-70 type 2: a wheelchair user and a companion, door 900.': 'EN 81-70 τύπου 2: ένας χρήστης αναπηρικού αμαξιδίου και ένας συνοδός, πόρτα 900.',
  'A bed and its attendants; 1400 × 2400 or 1500 × 2300 need 1500–1600 kg.': 'Ένα κρεβάτι και οι συνοδοί του· τα 1400 × 2400 ή 1500 × 2300 χρειάζονται 1500–1600 kg.',
