  'Survey points imported with the file\'s own numbers: they look like map coordinates, but their system is not one Lapin knows (Stereo 70, Lambert-93, UTM, Web Mercator, WGS 84). Name it in Manage → Location, or convert the drawing first.': 'Σημεία τοπογραφικής αποτύπωσης εισήχθησαν με τους δικούς τους αριθμούς του αρχείου: μοιάζουν με συντεταγμένες χάρτη, αλλά το σύστημά τους δεν είναι γνωστό στο Lapin (Stereo 70, Lambert-93, UTM, Web Mercator, WGS 84). Ονομάστε το στο Διαχείριση → Τοποθεσία ή μετατρέψτε πρώτα το σχέδιο.',
