  'The top of the element, above ±0.00: type it to move the element there': 'Η κορυφή του στοιχείου, πάνω από το ±0.00: πληκτρολογήστε την για να μετακινήσετε εκεί το στοιχείο',
  'The bottom of the element, above ±0.00: type it to move the element there': 'Ο πυθμένας του στοιχείου, πάνω από το ±0.00: πληκτρολογήστε τον για να μετακινήσετε εκεί το στοιχείο',
  'The base of the element, above ±0.00: type it to move the element there': 'Η βάση του στοιχείου, πάνω από το ±0.00: πληκτρολογήστε την για να μετακινήσετε εκεί το στοιχείο',
  'Standards a new project offers': 'Πρότυπα που προσφέρει ένα νέο έργο',
  'A project keeps only the profiles its types use, never a whole library: these are what its pickers offer. Manage → Profile libraries changes them for the project open.': 'Ένα έργο κρατά μόνο τα προφίλ που χρησιμοποιούν οι τύποι του, ποτέ ολόκληρη βιβλιοθήκη: αυτά προσφέρουν οι επιλογείς του. Το Διαχείριση → Βιβλιοθήκες προφίλ τα αλλάζει για το ανοιχτό έργο.',
  'Shown in the pickers': 'Εμφάνιση στους επιλογείς',
