  'No library yet.': 'Καμία βιβλιοθήκη ακόμη.',
  'Every standard, those added later too': 'Κάθε πρότυπο, και όσα προστεθούν αργότερα',
  'The standards shown: a click hides or shows one (kept for you, in every project)': 'Τα πρότυπα που εμφανίζονται: ένα κλικ κρύβει ή εμφανίζει ένα (διατηρείται για εσάς, σε κάθε έργο)',
  'Shown under': 'Εμφάνιση κάτω από',
  'The standard the pickers show its profiles under; empty: each profile\'s own, else the library\'s name': 'Το πρότυπο κάτω από το οποίο οι επιλογείς εμφανίζουν τα προφίλ του· κενό: το δικό του κάθε προφίλ, αλλιώς το όνομα της βιβλιοθήκης',
  'Standards in this project': 'Πρότυπα σε αυτό το έργο',
  'What its pickers offer; it keeps only the profiles its types use. Preferences → Profiles chooses them for new projects.': 'Αυτά που προσφέρουν οι επιλογείς του· κρατά μόνο τα προφίλ που χρησιμοποιούν οι τύποι του. Οι Προτιμήσεις → Προφίλ τα επιλέγουν για νέα έργα.',
