  'Elevation marker text': 'Κείμενο συμβόλου όψης',
  'The size of the section markers\' arrows (0.7 of it), in paper mm, in plans, sections, elevations, sheets and PDF; a section\'s own size in its properties goes before it': 'Το μέγεθος των βελών των συμβόλων τομής (0.7 αυτού), σε mm χαρτιού, σε κατόψεις, τομές, όψεις, φύλλα και PDF· το δικό του μέγεθος μιας τομής στις ιδιότητές της έχει προτεραιότητα',
  'The height of the section markers\' names, in paper mm; empty: the Standard text style\'s': 'Το ύψος των ονομάτων των συμβόλων τομής, σε mm χαρτιού· κενό: αυτό του στυλ κειμένου Standard',
  'The elevation markers\' circle across, in paper mm, in plans, sheets and PDF; an elevation\'s own size in its properties goes before it': 'Η διάμετρος του κύκλου των συμβόλων όψης, σε mm χαρτιού, σε κατόψεις, φύλλα και PDF· το δικό του μέγεθος μιας όψης στις ιδιότητές της έχει προτεραιότητα',
  'The height of the elevation markers\' names, in paper mm; empty: the Standard text style\'s': 'Το ύψος των ονομάτων των συμβόλων όψης, σε mm χαρτιού· κενό: αυτό του στυλ κειμένου Standard',
  'Drag: move the head (the section cuts the same); Ctrl/⌘-click: back on its end': 'Σύρετε: μετακίνηση της κεφαλής (η τομή κόβει το ίδιο)· Ctrl/⌘-κλικ: επιστροφή στο άκρο της',
