  'A head\'s offset is [dx, dy].': 'Η μετατόπιση μιας κεφαλής είναι [dx, dy].',
  'An elevation looks north, south, east or west: its marker is moved, not turned or mirrored.': 'Μια όψη κοιτάζει βορρά, νότο, ανατολή ή δύση: το σύμβολό της μετακινείται, δεν περιστρέφεται ούτε καθρεφτίζεται.',
