  'Light theme': 'Ανοιχτό θέμα',
  'Dark theme': 'Σκούρο θέμα',
  'A Lapin project. To work on it, open this file in Lapin: File → Open.': 'Ένα έργο Lapin. Για να εργαστείτε σε αυτό, ανοίξτε αυτό το αρχείο στο Lapin: Αρχείο → Άνοιγμα.',
  'A model exported from Lapin, to look at in a browser.': 'Ένα μοντέλο που εξήχθη από το Lapin, για προβολή σε περιηγητή.',
  'Exported': 'Εξήχθη',
  'This page was exported without the 3D model.': 'Αυτή η σελίδα εξήχθη χωρίς το τρισδιάστατο μοντέλο.',
  'Your browser cannot show 3D here (WebGL is off).': 'Το πρόγραμμα περιήγησής σας δεν μπορεί να εμφανίσει 3D εδώ (το WebGL είναι απενεργοποιημένο).',
  'No drawing was exported with this page.': 'Με αυτή τη σελίδα δεν εξήχθη κανένα σχέδιο.',
  'Fit the drawing': 'Προσαρμογή του σχεδίου στο παράθυρο',
  'Click an element in 3D, on a drawing or in a table to see its properties.': 'Κάντε κλικ σε ένα στοιχείο στο 3D, σε ένα σχέδιο ή σε έναν πίνακα για να δείτε τις ιδιότητές του.',
  'elements selected': 'επιλεγμένα στοιχεία',
  'Worked out from the model when the page was exported.': 'Υπολογίστηκε από το μοντέλο κατά την εξαγωγή της σελίδας.',
  'Indicative: priced by Lapin\'s own rough values, not yours.': 'Ενδεικτικό: τιμολογήθηκε με τις προσεγγιστικές τιμές του ίδιου του Lapin, όχι με τις δικές σας.',
  'Click a row to see its elements.': 'Κάντε κλικ σε μια γραμμή για να δείτε τα στοιχεία της.',
  'Lapin for the browser (.html)…': 'Lapin για το πρόγραμμα περιήγησης (.html)…',
  'Lapin for the browser': 'Lapin για το πρόγραμμα περιήγησης',
  'One .html file that opens by double-click in any browser, with no internet: the 3D model, the drawings, the estimate and every element\'s properties. With the project inside, File → Open in Lapin takes it back.': 'Ένα μόνο αρχείο .html που ανοίγει με διπλό κλικ σε οποιοδήποτε πρόγραμμα περιήγησης, χωρίς internet: το τρισδιάστατο μοντέλο, τα σχέδια, ο προϋπολογισμός και οι ιδιότητες κάθε στοιχείου. Με το έργο μέσα, το Αρχείο → Άνοιγμα στο Lapin το επαναφέρει.',
  'The project has no drawing yet.': 'Το έργο δεν έχει ακόμη κανένα σχέδιο.',
  '(no element)': '(κανένα στοιχείο)',
  'Shows no element of the model: left out unless you tick it': 'Δεν εμφανίζει κανένα στοιχείο του μοντέλου: παραλείπεται αν δεν το επιλέξετε',
  'The 3D model, as the 3D view shows it': 'Το τρισδιάστατο μοντέλο, όπως το δείχνει η προβολή 3D',
  'The estimate, worked out from the model now': 'Ο προϋπολογισμός, υπολογισμένος τώρα από το μοντέλο',
  'The project itself, so Lapin can open the page again': 'Το ίδιο το έργο, ώστε το Lapin να μπορεί να ανοίξει ξανά τη σελίδα',
  'Without it the page only shows the model: Lapin cannot open it': 'Χωρίς αυτό η σελίδα δείχνει μόνο το μοντέλο: το Lapin δεν μπορεί να την ανοίξει',
  'About': 'Πληροφορίες',
  'Opened the project inside the page. Save it as a .lapin to keep working on it.': 'Το έργο της σελίδας άνοιξε. Αποθηκεύστε το ως .lapin για να συνεχίσετε να εργάζεστε σε αυτό.',
  'Writing the page': 'Εγγραφή της σελίδας',
  'This web page was not written by Lapin: only a page Lapin exported (File → Lapin for the browser) opens as a project.': 'Αυτή η ιστοσελίδα δεν γράφτηκε από το Lapin: ως έργο ανοίγει μόνο μια σελίδα που εξήγαγε το Lapin (Αρχείο → Lapin για το πρόγραμμα περιήγησης).',
  'This Lapin page was exported without its project: it shows the model in a browser but cannot be opened. Export it again with the project included.': 'Αυτή η σελίδα Lapin εξήχθη χωρίς το έργο της: δείχνει το μοντέλο σε πρόγραμμα περιήγησης αλλά δεν μπορεί να ανοιχτεί. Εξαγάγετέ την ξανά με το έργο συμπεριλαμβανόμενο.',
  'Partition': 'Χώρισμα',
  'All partitions': 'Όλα τα χωρίσματα',
  'No partition': 'Χωρίς χώρισμα',
