  'Not shown in this view: hidden by its graphics, a filter, a phase, Hide / Isolate, its range or a level put away. A click or a box here does not take it.': 'Δεν εμφανίζεται σε αυτή την προβολή: κρύβεται από τα γραφικά του, ένα φίλτρο, μια φάση, το Απόκρυψη / Απομόνωση, την περιοχή του ή έναν κρυμμένο όροφο. Ένα κλικ ή ένα πλαίσιο εδώ δεν το επιλέγει.',
