  'Scripts are installed in the desktop app; the browser takes content packs only.': 'Τα σενάρια εγκαθίστανται στην εφαρμογή επιφάνειας εργασίας· το πρόγραμμα περιήγησης δέχεται μόνο πακέτα περιεχομένου.',
