  'Non-commercial': 'Μη εμπορική',
  'Signed by Lapin Extensions: Lapin checks the catalogue\'s signature and each file\'s SHA-256.': 'Υπογεγραμμένο από το Lapin Extensions: το Lapin ελέγχει την υπογραφή του καταλόγου και το SHA-256 κάθε αρχείου.',
  'This catalogue is not signed by Lapin Extensions: install from it only if you trust who keeps it.': 'Αυτός ο κατάλογος δεν είναι υπογεγραμμένος από το Lapin Extensions: εγκαταστήστε από αυτόν μόνο αν εμπιστεύεστε όποιον τον διαχειρίζεται.',
  'The catalogue’s signature does not hold: it may have been changed. It was not read.': 'Η υπογραφή του καταλόγου δεν ισχύει: ίσως έχει αλλάξει. Δεν διαβάστηκε.',
  'Lapin’s catalogue is not signed as it should be. It was not read; try again later.': 'Ο κατάλογος του Lapin δεν είναι υπογεγραμμένος όπως πρέπει. Δεν διαβάστηκε· δοκιμάστε ξανά αργότερα.',
  'The package is not signed by the catalogue: it was not installed.': 'Το πακέτο δεν είναι υπογεγραμμένο από τον κατάλογο: δεν εγκαταστάθηκε.',
  'The package’s signature does not hold: it was not installed.': 'Η υπογραφή του πακέτου δεν ισχύει: δεν εγκαταστάθηκε.',
  'The package has no address to read it from.': 'Το πακέτο δεν έχει διεύθυνση από την οποία να διαβαστεί.',
  'Its licence forbids commercial use: not for paid work': 'Η άδεια χρήσης του απαγορεύει την εμπορική χρήση: όχι για αμειβόμενη εργασία',
  'Its types go into the project open now (one step to undo): materials matched by name or made, a type already there the same reused. Installed → Add its types to this project brings them into another.': 'Οι τύποι του μπαίνουν στο ανοιχτό έργο τώρα (ένα βήμα αναίρεσης): τα υλικά αντιστοιχίζονται με βάση το όνομα ή δημιουργούνται, ένας τύπος που υπάρχει ήδη και είναι ίδιος επαναχρησιμοποιείται. Το Εγκατεστημένες → Προσθήκη των τύπων του σε αυτό το έργο τους φέρνει σε άλλο.',
  'Add its types to this project': 'Προσθήκη των τύπων του σε αυτό το έργο',
  'Type packs': 'Πακέτα τύπων',
  'Choose the types to add. Their materials are the project\'s when it has one of the same name, else made; a type already in the project the same is reused, one of the same name that differs is added beside it with (2) after its name. One step to undo.': 'Επιλέξτε τους τύπους προς προσθήκη. Τα υλικά τους είναι του έργου όταν έχει ένα με το ίδιο όνομα, αλλιώς δημιουργούνται· ένας τύπος που υπάρχει ήδη στο έργο και είναι ίδιος επαναχρησιμοποιείται, ένας με το ίδιο όνομα που διαφέρει προστίθεται δίπλα με (2) μετά το όνομά του. Ένα βήμα αναίρεσης.',
  'a type of this name is in the project': 'ένας τύπος με αυτό το όνομα υπάρχει στο έργο',
