  'Some loads find nothing under them (no bar, slab or wall within reach) and are left out: see the notes below.': 'Ορισμένα φορτία δεν βρίσκουν τίποτα από κάτω τους (καμία ράβδο, πλάκα ή τοίχο εντός εμβέλειας) και παραλείπονται: δείτε τις σημειώσεις παρακάτω.',
  'The structure is a mechanism: it can move without resistance.': 'Ο φορέας είναι μηχανισμός: μπορεί να κινηθεί χωρίς αντίσταση.',
