  'Rotation about local axis 2': 'Στροφή περί τον τοπικό άξονα 2',
  'Rotation about local axis 3 (strong axis)': 'Στροφή περί τον τοπικό άξονα 3 (ισχυρός άξονας)',
  'A ticked freedom is released at that end. Default: what the connection says (a cleat or gusset pins), a timber roof member pinned about its strong axis, any other bar fixed.': 'Ένας επιλεγμένος βαθμός ελευθερίας αποδεσμεύεται σε εκείνο το άκρο. Προεπιλογή: ό,τι λέει η σύνδεση (ένας σύνδεσμος ή κόμβος αρθρώνει), ένα μέλος ξύλινης στέγης αρθρωμένο περί τον ισχυρό άξονά του, κάθε άλλη ράβδος πακτωμένη.',
  'Analyse the frame under these loads and show the results': 'Ανάλυση του πλαισίου υπό αυτά τα φορτία και εμφάνιση των αποτελεσμάτων',
  'Keep the project\'s': 'Διατήρηση του υπάρχοντος στο έργο',
  'Update the project\'s': 'Ενημέρωση του υπάρχοντος στο έργο',
  'Skip': 'Παράλειψη',
  'Materials the project already has, defined otherwise': 'Υλικά που έχει ήδη το έργο, ορισμένα διαφορετικά',
  'What differs': 'Τι διαφέρει',
  'The same choice for every material': 'Η ίδια επιλογή για κάθε υλικό',
  'Apply to all…': 'Εφαρμογή σε όλα…',
  'Types the project already has, made otherwise': 'Τύποι που έχει ήδη το έργο, φτιαγμένοι διαφορετικά',
  'The same choice for every type': 'Η ίδια επιλογή για κάθε τύπο',
  'Keep both makes the library\'s beside the project\'s, with (2) after its name. Updating changes the project\'s in place: what uses it follows. One step to undo.': 'Το Διατήρηση και των δύο βάζει τον τύπο της βιβλιοθήκης δίπλα στου έργου, με (2) μετά το όνομά του. Η ενημέρωση αλλάζει τον τύπο του έργου επιτόπου: ό,τι τον χρησιμοποιεί τον ακολουθεί. Ένα βήμα αναίρεσης.',
  'Types made': 'Τύποι που δημιουργήθηκαν',
  'Types changed': 'Τύποι που άλλαξαν',
  'Types already in the project': 'Τύποι που υπάρχουν ήδη στο έργο',
  'Types skipped': 'Τύποι που παραλείφθηκαν',
  'Materials made': 'Υλικά που δημιουργήθηκαν',
  'Materials updated': 'Υλικά που ενημερώθηκαν',
  'Materials kept as the project\'s': 'Υλικά που διατηρήθηκαν ως του έργου',
  'Made beside, renamed': 'Δημιουργήθηκαν δίπλα, με νέο όνομα',
  'The import failed.': 'Η εισαγωγή απέτυχε.',
  'section hatch': 'διαγράμμιση τομής',
  'plan hatch': 'διαγράμμιση κάτοψης',
  'elevation hatch': 'διαγράμμιση όψης',
