  'The red cross is the insertion point and the arrow the symbol\'s direction: draw the symbol round it. Draw with the tools on the left; insert live fields from the list below.': 'Ο κόκκινος σταυρός είναι το σημείο εισαγωγής και το βέλος η κατεύθυνση του συμβόλου: σχεδιάστε το σύμβολο γύρω από αυτό. Σχεδιάστε με τα εργαλεία αριστερά· εισαγάγετε ζωντανά πεδία από τη λίστα παρακάτω.',
