  'Lapin\'s own symbols are read only: duplicate one in Manage → Symbols…': 'Τα σύμβολα του ίδιου του Lapin είναι μόνο για ανάγνωση: αντιγράψτε ένα στο Διαχείριση → Σύμβολα…',
