  'This view has no drafted lines, polylines, arcs or circles.': 'Αυτή η προβολή δεν έχει σχεδιασμένες γραμμές, πολυγραμμές, τόξα ή κύκλους.',
  'Give each layer what it becomes; layers left as they are stay drafting. The map is kept on this computer by layer name.': 'Δώστε σε κάθε επίπεδο αυτό που γίνεται· τα επίπεδα που μένουν όπως είναι παραμένουν σχεδίαση. Η αντιστοίχιση φυλάσσεται σε αυτόν τον υπολογιστή με βάση το όνομα του επιπέδου.',
