  'Import map…': 'Εισαγωγή αντιστοίχισης…',
  'The layer map was saved as a .lapinmapping file.': 'Η αντιστοίχιση επιπέδων αποθηκεύτηκε ως αρχείο .lapinmapping.',
  'Open a plan, a section or an elevation to convert its drafting.': 'Ανοίξτε μια κάτοψη, μια τομή ή μια όψη για να μετατρέψετε τη σχεδίασή της.',
  'Select drafted lines, polylines, arcs or circles to convert.': 'Επιλέξτε σχεδιασμένες γραμμές, πολυγραμμές, τόξα ή κύκλους για μετατροπή.',
  'Blocks': 'Μπλοκ',
  'keep as symbols': 'διατήρηση ως σύμβολα',
  'Each block of the file becomes a symbol of the project, each insert an instance placed, turned and turned over as it was; without: the blocks are exploded into lines': 'Κάθε μπλοκ του αρχείου γίνεται σύμβολο του έργου, κάθε εισαγωγή ένα στιγμιότυπο τοποθετημένο, περιστραμμένο και αναστραμμένο όπως ήταν· χωρίς αυτό: τα μπλοκ αναλύονται σε γραμμές',
  'Then': 'Μετά',
  'convert its layers to elements…': 'μετατροπή των επιπέδων του σε στοιχεία…',
  'Opens Convert layers… after the import: A-WALL to walls, A-COLS to columns, steel layers to bars': 'Ανοίγει το Μετατροπή επιπέδων… μετά την εισαγωγή: A-WALL σε τοίχους, A-COLS σε υποστυλώματα, επίπεδα χάλυβα σε ράβδους',
  'Spreadsheet or CSV': 'Λογιστικό φύλλο ή CSV',
  'Mapping (.lapinmapping)': 'Αντιστοίχιση (.lapinmapping)',
  '+ Classification…': '+ Ταξινόμηση…',
  'A .lapinbarshapes file: shapes the project lacks are added, those with the same code are updated': 'Ένα αρχείο .lapinbarshapes: τα σχήματα που λείπουν από το έργο προστίθενται, αυτά με τον ίδιο κωδικό ενημερώνονται',
  'A .lapinrules file: it comes in as a pack of the project\'s': 'Ένα αρχείο .lapinrules: έρχεται ως πακέτο του έργου',
  'A .lapinstandards file: what the project lacks is added; what it has made otherwise asks': 'Ένα αρχείο .lapinstandards: ό,τι λείπει από το έργο προστίθεται· ό,τι έχει φτιαγμένο διαφορετικά ρωτά',
  'A CSV or Excel file or pasted cells: code, title, parent code': 'Ένα αρχείο CSV ή Excel ή επικολλημένα κελιά: κωδικός, τίτλος, κωδικός γονέα',
  'A GLB of your own, with its licence: its materials given roles, its stretch zones set': 'Ένα δικό σας GLB, με την άδεια χρήσης του: στα υλικά του δίνονται ρόλοι, ορίζονται οι ζώνες επέκτασής του',
  'A choice parameter needs its choices, separated by commas.': 'Μια παράμετρος επιλογής χρειάζεται τις επιλογές της, χωρισμένες με κόμματα.',
  'A copy of this type in the project, to change': 'Ένα αντίγραφο αυτού του τύπου στο έργο, για αλλαγή',
  'A parameter\'s key, or a formula (A - 2 * R1)': 'Το κλειδί μιας παραμέτρου ή ένας τύπος (A - 2 * R1)',
  'A roof pitched under its covering\'s least pitch is warned of, as it may not shed water.': 'Μια στέγη με κλίση κάτω από την ελάχιστη κλίση της επικάλυψής της προειδοποιείται, καθώς μπορεί να μην απορρέει το νερό.',
  'A set of your own, started from the residential one': 'Ένα δικό σας σύνολο, ξεκινώντας από το κατοικιών',
  'A table of elements (by GlobalId, mark or name) and their codes in this system': 'Ένας πίνακας στοιχείων (με GlobalId, σήμανση ή όνομα) και των κωδικών τους σε αυτό το σύστημα',
  'A type of this model gives a material to each role: upholstery, legs, glass… The materials with the same role take the same colour.': 'Ένας τύπος αυτού του μοντέλου δίνει ένα υλικό σε κάθε ρόλο: ταπετσαρία, πόδια, γυαλί… Τα υλικά με τον ίδιο ρόλο παίρνουν το ίδιο χρώμα.',
  'Add a classification field to the text: {classification.code}, {classification.title}, or a system\'s own code': 'Προσθέστε ένα πεδίο ταξινόμησης στο κείμενο: {classification.code}, {classification.title} ή τον δικό κωδικό ενός συστήματος',
  'Add the steel': 'Προσθήκη του χάλυβα',
  'Along a zone the model stretches; outside it the ends keep their size (a sofa\'s arms, a table\'s legs). An axis without a zone scales whole.': 'Κατά μήκος μιας ζώνης το μοντέλο επεκτείνεται· εκτός αυτής τα άκρα κρατούν το μέγεθός τους (τα μπράτσα ενός καναπέ, τα πόδια ενός τραπεζιού). Ένας άξονας χωρίς ζώνη κλιμακώνεται ολόκληρος.',
  'Also the project\'s options (units, scales, marker sizes, object styles, pen table, marker symbols)': 'Επίσης οι επιλογές του έργου (μονάδες, κλίμακες, μεγέθη σημάνσεων, στυλ αντικειμένων, πίνακας πέννων, σύμβολα σήμανσης)',
  'An AutoCAD line type file: its dashes and gaps are kept, text and shapes in a line are left out': 'Ένα αρχείο τύπων γραμμής AutoCAD: οι παύλες και τα κενά του διατηρούνται, τα κείμενα και τα σχήματα σε μια γραμμή παραλείπονται',
  'Apply to stair types': 'Εφαρμογή σε τύπους σκάλας',
