  'Decimals with a dot; arguments separated by , or ;. A name with spaces may be written without them (Fire rating or FireRating).': 'Δεκαδικά με τελεία· ορίσματα χωρισμένα με , ή ;. Ένα όνομα με κενά μπορεί να γραφτεί χωρίς αυτά (Fire rating ή FireRating).',
  'Degrees, counter-clockwise, from this leg to the next (none after the last); a key or a formula too': 'Μοίρες, αριστερόστροφα, από αυτό το σκέλος στο επόμενο (καμία μετά το τελευταίο)· επίσης κλειδί ή τύπος',
  'Delete this classification?': 'Διαγραφή αυτής της ταξινόμησης?',
