  'Import model (GLB)…': 'Εισαγωγή μοντέλου (GLB)…',
  'Import standards…': 'Εισαγωγή προτύπων…',
  'In use': 'Σε χρήση',
  'Keep both makes the file\'s beside the project\'s, with a number after its name. Updating changes the project\'s in place. One step to undo.': 'Το Διατήρηση και των δύο βάζει αυτά του αρχείου δίπλα σε αυτά του έργου, με έναν αριθμό μετά το όνομα. Η ενημέρωση αλλάζει αυτά του έργου επιτόπου. Ένα βήμα αναίρεσης.',
  'Lapin ships no classification: the system\'s licence is yours. Codes are put on elements and types in their properties, or from a table (Import table… → Classification codes on elements).': 'Το Lapin δεν περιλαμβάνει καμία ταξινόμηση: η άδεια χρήσης του συστήματος είναι δική σας. Οι κωδικοί μπαίνουν σε στοιχεία και τύπους στις ιδιότητές τους ή από πίνακα (Εισαγωγή πίνακα… → Κωδικοί ταξινόμησης σε στοιχεία).',
  'Lapin\'s': 'Του Lapin',
  'Lapin\'s rules stay as they are: Duplicate them to change the values.': 'Οι κανόνες του Lapin μένουν όπως είναι: Αντιγράψτε τους για να αλλάξετε τις τιμές.',
  'Least hook tail': 'Ελάχιστη ουρά αγκίστρου',
  'Least pitch': 'Ελάχιστη κλίση',
  'Leg': 'Σκέλος',
  'Lengths are in the project\'s unit. A leg\'s length is a parameter\'s key (A) or a formula (A - 2 * R1); the turn is in degrees, counter-clockwise. Bars of the shape follow a change to it.': 'Τα μήκη είναι στη μονάδα του έργου. Το μήκος ενός σκέλους είναι το κλειδί μιας παραμέτρου (A) ή ένας τύπος (A - 2 * R1)· η στροφή είναι σε μοίρες, αριστερόστροφα. Οι ράβδοι του σχήματος ακολουθούν μια αλλαγή σε αυτό.',
  'Line types': 'Τύποι γραμμής',
  'Line types in the file': 'Τύποι γραμμής στο αρχείο',
  'Lists what the project has that differs from the rules in use': 'Παραθέτει ό,τι έχει το έργο και διαφέρει από τους κανόνες που χρησιμοποιούνται',
  'Make a bar shape first: Bar shapes…': 'Φτιάξτε πρώτα ένα σχήμα ράβδου: Σχήματα ράβδων…',
  'Manage → Classifications…': 'Διαχείριση → Ταξινομήσεις…',
  'Mandrel (bend diameter, a factor of Ø, by the bar\'s diameter)': 'Μανδρέλι (διάμετρος κάμψης, συντελεστής του Ø, ανά διάμετρο της ράβδου)',
  'Material in the file': 'Υλικό στο αρχείο',
  'Materials of the file → roles': 'Υλικά του αρχείου → ρόλοι',
  'Model imported: ${r.materials.length} materials to give a role.': 'Το μοντέλο εισήχθη: ${r.materials.length} υλικά για να τους δοθεί ρόλος.',
  'My models': 'Τα μοντέλα μου',
  'Names and functions': 'Ονόματα και συναρτήσεις',
  'New bars take the steel and the hooks\' tails from here, and the bend radius when the mandrel differs from Lapin\'s. Bars of a steel or a diameter not offered are listed by the check, not refused.': 'Οι νέες ράβδοι παίρνουν τον χάλυβα και τις ουρές των αγκίστρων από εδώ, και την ακτίνα κάμψης όταν το μανδρέλι διαφέρει από του Lapin. Ράβδοι χάλυβα ή διαμέτρου που δεν προσφέρεται απαριθμούνται από τον έλεγχο, δεν απορρίπτονται.',
  'New set\'s name': 'Όνομα νέου συνόλου',
  'New steel': 'Νέος χάλυβας',
  'New, Existing, Demolish': 'Νέο, Υπάρχον, Κατεδάφιση',
  'No classification in the project yet:': 'Καμία ταξινόμηση στο έργο ακόμη:',
  'No items yet.': 'Κανένα στοιχείο ακόμη.',
  'No shared parameters yet. A definition fixes a parameter\'s name, kind and property set, so every element and every tag means the same thing by it.': 'Καμία κοινόχρηστη παράμετρος ακόμη. Ένας ορισμός καθορίζει το όνομα, το είδος και το σύνολο ιδιοτήτων μιας παραμέτρου, ώστε κάθε στοιχείο και κάθε ετικέτα να εννοούν το ίδιο με αυτή.',
  'None of your own yet. Make one: its code as your standard names it, its parameters and its legs.': 'Καμία δική σας ακόμη. Φτιάξτε μία: ο κωδικός της όπως τον ονομάζει το πρότυπό σας, οι παράμετροι και τα σκέλη της.',
  'None of your own yet: make one, or import a .lin file.': 'Καμία δική σας ακόμη: φτιάξτε μία ή εισαγάγετε ένα αρχείο .lin.',
  'None yet. A GLB (binary glTF) comes in with its licence; its size and materials are read from the file.': 'Κανένα ακόμη. Ένα GLB (δυαδικό glTF) έρχεται με την άδεια χρήσης του· το μέγεθος και τα υλικά του διαβάζονται από το αρχείο.',
  'None yet. Make one, then Import items from a table (a CSV or Excel file of the system you hold the licence of); or keep the office\'s own keynotes.': 'Κανένα ακόμη. Φτιάξτε ένα και μετά Εισαγωγή στοιχείων από πίνακα (αρχείο CSV ή Excel του συστήματος του οποίου έχετε την άδεια)· ή κρατήστε τις δικές σας κωδικοποιημένες σημειώσεις του γραφείου.',
  'Nothing differs from the rules in use.': 'Τίποτα δεν διαφέρει από τους κανόνες που χρησιμοποιούνται.',
  'Or type them: 6 2 1 2': 'Ή πληκτρολογήστε τες: 6 2 1 2',
  'Paper millimetres, a dash then its gap, repeated along the line:': 'Χιλιοστά χαρτιού, μια παύλα και μετά το κενό της, επαναλαμβανόμενα κατά μήκος της γραμμής:',
  'Plan symbol': 'Σύμβολο κάτοψης',
