  'That set exists already, or its name is too long.': 'Αυτό το σύνολο υπάρχει ήδη ή το όνομά του είναι πολύ μεγάλο.',
  'The IFC property set it goes to; empty: Lapin_Parameters. A set of yours never starts with Pset_.': 'Το σύνολο ιδιοτήτων IFC στο οποίο πηγαίνει· κενό: Lapin_Parameters. Ένα δικό σας σύνολο δεν ξεκινά ποτέ με Pset_.',
  'The code is added to the system as a keynote of your own (a title may follow the code)': 'Ο κωδικός προστίθεται στο σύστημα ως δική σας κωδικοποιημένη σημείωση (ένας τίτλος μπορεί να ακολουθεί τον κωδικό)',
  'The file has no line types Lapin can read (a .lin file: *NAME, then A, dash, -gap, …).': 'Το αρχείο δεν έχει τύπους γραμμής που μπορεί να διαβάσει το Lapin (αρχείο .lin: *ΟΝΟΜΑ, μετά A, παύλα, -κενό, …).',
  'The first 500 matches: narrow the search.': 'Οι πρώτες 500 αντιστοιχίες: περιορίστε την αναζήτηση.',
