  'The height its underside hangs at (a wall lamp, an upper unit); 0: on the floor': 'Το ύψος στο οποίο κρέμεται η κάτω πλευρά του (φωτιστικό τοίχου, ντουλάπι οροφής)· 0: στο δάπεδο',
