  'The same choice for every line type that differs': 'Η ίδια επιλογή για κάθε τύπο γραμμής που διαφέρει',
  'The set a stair type takes is chosen in its Rules tab; a new type starts from these values. A stair that differs is warned of, never refused.': 'Το σύνολο που παίρνει ένας τύπος σκάλας επιλέγεται στην καρτέλα Κανόνες του· ένας νέος τύπος ξεκινά από αυτές τις τιμές. Μια σκάλα που διαφέρει προειδοποιείται, ποτέ δεν απορρίπτεται.',
  'The shape codes and dimensions are those of the bar shapes (Bar shapes…). Bars laid by a type (stirrups, column bars) have no drawn shape and are not listed here.': 'Οι κωδικοί σχημάτων και οι διαστάσεις είναι αυτά των σχημάτων ράβδων (Σχήματα ράβδων…). Οι ράβδοι που τοποθετούνται από έναν τύπο (συνδετήρες, ράβδοι υποστυλώματος) δεν έχουν σχεδιασμένο σχήμα και δεν παρατίθενται εδώ.',
  'The styles, tag types, layers, line types, hatches and symbols as a .lapinstandards file, for another project or computer': 'Τα στυλ, οι τύποι ετικετών, τα επίπεδα, οι τύποι γραμμής, οι διαγραμμίσεις και τα σύμβολα ως αρχείο .lapinstandards, για άλλο έργο ή υπολογιστή',
  'The symbol a plan draws this piece with (Manage → Symbols…); none: its body seen from above': 'Το σύμβολο με το οποίο σχεδιάζει μια κάτοψη αυτό το κομμάτι (Διαχείριση → Σύμβολα…)· κανένα: το σώμα του όπως φαίνεται από πάνω',
  'The text or shapes in the line are left out; its dashes are kept': 'Τα κείμενα ή τα σχήματα στη γραμμή παραλείπονται· οι παύλες της διατηρούνται',
