  'Kept in this computer\'s type packs: any project here can add them (Catalog)': 'Φυλάσσεται στα πακέτα τύπων αυτού του υπολογιστή: κάθε έργο εδώ μπορεί να τα προσθέσει (Κατάλογος)',
