  'A body is made only when its condition is not 0: a yes/no parameter or a comparison. Decimals with a dot; arguments separated by , or ;.': 'Ένα σώμα δημιουργείται μόνο όταν η συνθήκη του δεν είναι 0: μια παράμετρος ναι/όχι ή μια σύγκριση. Δεκαδικά με τελεία· ορίσματα χωρισμένα με , ή ;.',
