  'Layers 1 to n from the R face (right of the drawn direction) to the L face, as in the picture. Wall drawn anticlockwise: R is the exterior, L the interior. The core carries the wall\'s axis.': 'Οι στρώσεις 1 έως n από την όψη Δ (δεξιά της κατεύθυνσης σχεδίασης) προς την όψη Α, όπως στην εικόνα. Τοίχος σχεδιασμένος αριστερόστροφα: το Δ είναι το εξωτερικό, το Α το εσωτερικό. Ο πυρήνας φέρει τον άξονα του τοίχου.',
  'Reverse layers': 'Αντιστροφή στρώσεων',
  'Run the layers the other way: the R face\'s layer goes to the L face. Walls of the type swap faces once it is saved': 'Αντιστρέφει τη σειρά των στρώσεων: η στρώση της όψης Δ πηγαίνει στην όψη Α. Οι τοίχοι του τύπου αλλάζουν όψεις μόλις αποθηκευτεί',
