  'Run the layers the other way: the top layer goes to the underside. Floors of the type follow once it is saved': 'Αντιστρέφει τη σειρά των στρώσεων: η πάνω στρώση πηγαίνει στην κάτω πλευρά. Οι πλάκες του τύπου ακολουθούν μόλις αποθηκευτεί',
