  'Kept in this computer\'s library: any project can make a schedule from it.': 'Διατηρήθηκε στη βιβλιοθήκη αυτού του υπολογιστή: κάθε έργο μπορεί να φτιάξει έναν πίνακα από αυτό.',
  'New schedule from a template': 'Νέος πίνακας από πρότυπο',
  'A template is a field schedule\'s setup: its filter, grouping and columns. Save one from a field schedule (Template…), then make a schedule from it in any project.': 'Ένα πρότυπο είναι η ρύθμιση ενός πίνακα πεδίων: το φίλτρο, η ομαδοποίηση και οι στήλες του. Αποθηκεύστε ένα από έναν πίνακα πεδίων (Πρότυπο…) και μετά φτιάξτε έναν πίνακα από αυτό σε οποιοδήποτε έργο.',
  'No template kept yet.': 'Δεν έχει διατηρηθεί ακόμη κανένα πρότυπο.',
  'From a file…': 'Από αρχείο…',
  'That file is not a schedule template.': 'Αυτό το αρχείο δεν είναι πρότυπο πίνακα.',
  'A field schedule lists any field of the elements, the model\'s own and those a file brings (a property of an imported IFC): filter them, group them and add up their values. It follows the model.': 'Ένας πίνακας πεδίων απαριθμεί οποιοδήποτε πεδίο των στοιχείων, αυτά του ίδιου του μοντέλου και όσα φέρνει ένα αρχείο (μια ιδιότητα από εισαγμένο IFC): φιλτράρετέ τα, ομαδοποιήστε τα και αθροίστε τις τιμές τους. Ακολουθεί το μοντέλο.',
