  'exists': 'υπάρχει',
  'missing': 'λείπει',
  'Group by': 'Ομαδοποίηση κατά',
  'One row for each different value of these fields, in this order. Nothing here: one row for each element.': 'Μία γραμμή για κάθε διαφορετική τιμή αυτών των πεδίων, με αυτή τη σειρά. Τίποτα εδώ: μία γραμμή για κάθε στοιχείο.',
  'A field or a formula (= NetSideArea * 1.1). When rows are grouped, the aggregate says how a column\'s values are added up.': 'Ένα πεδίο ή ένας τύπος (= NetSideArea * 1.1). Όταν οι γραμμές ομαδοποιούνται, η άθροιση λέει πώς προστίθενται οι τιμές μιας στήλης.',
