  'By another field': 'Κατά άλλο πεδίο',
  'Your office\'s names for fields. A name reads the first source an element has: Phase ← Pset_Firma.Etapa, then ArchiCADProperties.Faza. Schedules, tags, formulas and filters then ask for the name, whichever file the element comes from.': 'Τα ονόματα που δίνει το γραφείο σας στα πεδία. Ένα όνομα διαβάζει την πρώτη πηγή που έχει ένα στοιχείο: Phase ← Pset_Firma.Etapa, μετά ArchiCADProperties.Faza. Οι πίνακες, οι ετικέτες, οι τύποι και τα φίλτρα ζητούν έτσι το όνομα, από όποιο αρχείο κι αν προέρχεται το στοιχείο.',
  'Remove the name': 'Αφαίρεση του ονόματος',
