  'Quantity from field': 'Ποσότητα από πεδίο',
  'Instead of the built-in measure, under the step\'s norm: a field, or a formula (= Firma.Volum * 1.05)': 'Αντί για το ενσωματωμένο μέγεθος, κάτω από τον κανόνα του βήματος: ένα πεδίο ή ένας τύπος (= Firma.Volum * 1.05)',
  'Read from each of its elements and added up: a field, or a formula (= Firma.Volum * 1.05). The days of the elements, rounded up.': 'Διαβάζεται από καθένα από τα στοιχεία της και αθροίζεται: ένα πεδίο ή ένας τύπος (= Firma.Volum * 1.05). Οι ημέρες των στοιχείων, στρογγυλοποιημένες προς τα πάνω.',
  'Instead of the built-in measure, under the norm: a field, or a formula': 'Αντί για το ενσωματωμένο μέγεθος, κάτω από τον κανόνα: ένα πεδίο ή ένας τύπος',
  'Its norm\'s code (Planning → Generate schedule… → Durations lists the norms)': 'Ο κωδικός του κανόνα της (Προγραμματισμός → Δημιουργία χρονοδιαγράμματος… → οι Διάρκειες απαριθμούν τους κανόνες)',
  'People working together': 'Άνθρωποι που εργάζονται μαζί',
  'Retime from fields': 'Επανυπολογισμός χρόνων από πεδία',
  'Every task with a duration or quantity from a field, worked out again from the model as it is now': 'Κάθε εργασία με διάρκεια ή ποσότητα από πεδίο, υπολογισμένη ξανά από το μοντέλο όπως είναι τώρα',
  'Every task timed from a field, worked out again from the model as it is now': 'Κάθε εργασία με χρόνο από πεδίο, υπολογισμένη ξανά από το μοντέλο όπως είναι τώρα',
  'Type a formula such as = Firma.Volum * 1.05': 'Πληκτρολογήστε έναν τύπο όπως = Firma.Volum * 1.05',
  'Take it off': 'Αφαίρεση',
  '(no value)': '(χωρίς τιμή)',
  'Display…': 'Εμφάνιση…',
  'Colour the bars, group the rows and add columns by any field of the elements': 'Χρωματίστε τις ράβδους, ομαδοποιήστε τις γραμμές και προσθέστε στήλες με οποιοδήποτε πεδίο των στοιχείων',
  'Display by fields': 'Εμφάνιση κατά πεδία',
  'Any field of the tasks\' elements: the model\'s own, a file\'s property, or the office\'s field names.': 'Οποιοδήποτε πεδίο των στοιχείων των εργασιών: του ίδιου του μοντέλου, μια ιδιότητα αρχείου ή τα ονόματα πεδίων του γραφείου.',
  'The rows of the window grouped by the value, each group under a header; the tasks that do the work only. The sheet keeps the WBS order.': 'Οι γραμμές του παραθύρου ομαδοποιούνται κατά την τιμή, κάθε ομάδα κάτω από μια επικεφαλίδα· μόνο οι εργασίες που κάνουν τη δουλειά. Το φύλλο κρατά τη σειρά WBS.',
  'No task has this field.': 'Καμία εργασία δεν έχει αυτό το πεδίο.',
  'Retimed from fields': 'Επανυπολογίστηκε από πεδία',
  'No task takes its duration or quantity from a field.': 'Καμία εργασία δεν παίρνει τη διάρκεια ή την ποσότητά της από πεδίο.',
