  'My palettes': 'Οι παλέτες μου',
  'What the colour fields\' swatch button offers: the colours chosen lately (automatic), the project\'s palette and your own palettes.': 'Τι προσφέρει το κουμπί δειγμάτων των πεδίων χρώματος: τα χρώματα που επιλέχθηκαν πρόσφατα (αυτόματα), η παλέτα του έργου και οι δικές σας παλέτες.',
  'Selection and preselection': 'Επιλογή και προεπιλογή',
  'Preselection highlight: light up what the cursor is over before a click, in plans, sections, sheets and 3D': 'Επισήμανση προεπιλογής: φωτίζει ό,τι βρίσκεται κάτω από τον δείκτη πριν από το κλικ, σε κατόψεις, τομές, φύλλα και 3D',
