  'A wall opening of the shape\'s outline, in the wall the view looks at.': 'Ένα άνοιγμα τοίχου με το περίγραμμα του σχήματος, στον τοίχο που κοιτάζει η προβολή.',
  'Its centre, the end of one semi-axis, then the other semi-axis': 'Το κέντρο του, το άκρο ενός ημιάξονα και μετά ο άλλος ημιάξονας',
