  'Click inside a closed drafted shape: a polyline, a rectangle, a circle': 'Κάντε κλικ μέσα σε ένα κλειστό σχεδιασμένο σχήμα: μια πολυγραμμή, ένα ορθογώνιο, έναν κύκλο',
