  'Sold by its author through their own shop: the seller takes the payment, issues the invoice and handles refunds. Lapin Extensions takes no commission.': 'Πωλείται από τον δημιουργό της μέσω του δικού του καταστήματος: ο πωλητής εισπράττει την πληρωμή, εκδίδει το τιμολόγιο και χειρίζεται τις επιστροφές χρημάτων. Το Lapin Extensions δεν παίρνει προμήθεια.',
  'Its licence is no longer valid (refunded or disabled by its seller): it gets no more updates. What is installed stays.': 'Η άδειά της δεν ισχύει πια (επιστράφηκαν τα χρήματα ή απενεργοποιήθηκε από τον πωλητή): δεν λαμβάνει πλέον ενημερώσεις. Ό,τι είναι εγκατεστημένο παραμένει.',
