  'Lapin sends the key to the store, which checks it with the seller\'s shop; the key stays on this computer.': 'Το Lapin στέλνει το κλειδί στο κατάστημα, που το ελέγχει με το κατάστημα του πωλητή· το κλειδί παραμένει σε αυτόν τον υπολογιστή.',
