  'Forget the licence key kept for {name}? What is installed stays; an update will ask for the key again.': 'Να διαγραφεί το κλειδί άδειας που κρατήθηκε για το {name}; Ό,τι είναι εγκατεστημένο παραμένει· μια ενημέρωση θα ζητήσει ξανά το κλειδί.',
  'Enter the licence key you received from the seller.': 'Εισαγάγετε το κλειδί άδειας που λάβατε από τον πωλητή.',
  'This is not a licence key of this extension: check the key in the seller\'s e-mail.': 'Αυτό δεν είναι κλειδί άδειας αυτής της επέκτασης: ελέγξτε το κλειδί στο e-mail του πωλητή.',
  'This licence key is no longer valid: its purchase was refunded, or its seller disabled it.': 'Αυτό το κλειδί άδειας δεν ισχύει πια: η αγορά επιστράφηκε ή ο πωλητής το απενεργοποίησε.',
  'The store could not check the licence key just now: try again later.': 'Το κατάστημα δεν μπόρεσε να ελέγξει το κλειδί άδειας αυτή τη στιγμή: δοκιμάστε ξανά αργότερα.',
