  'A type\'s property sets (Pset_WallCommon.IsExternal on the wall type) also written on each element of the type, for programs that read only the element; an element\'s own value wins': 'Τα σύνολα ιδιοτήτων ενός τύπου (Pset_WallCommon.IsExternal στον τύπο τοίχου) γράφονται και σε κάθε στοιχείο του τύπου, για προγράμματα που διαβάζουν μόνο το στοιχείο· η δική του τιμή του στοιχείου υπερισχύει',
  'Type properties': 'Ιδιότητες τύπου',
